    def _write_bound_seed(self, tmp: str) -> tuple[Path, Path]:
        root = Path(tmp)
        artifact = root / "hack" / "semgrep.json"
        artifact.parent.mkdir(parents=True, exist_ok=True)
        artifact.write_text("{}\n")
        payload = self._valid_seed_payload()
        payload["artifact_paths"] = [str(artifact)]
        payload["code_analysis_sources"] = [{"source_type": "semgrep", "source": str(artifact), "quote_or_fact": "Semgrep parser command auth route source/sink candidate."}]
        recommended = payload["recommended_fuzzing_lanes"]
        assert isinstance(recommended, list)
        for item in recommended:
            item["supporting_sources"][0]["source"] = str(artifact)
        seed_json = root / "seed.json"
        validation_json = root / "seed.validation.json"
        seed_json.write_text(json.dumps(payload, indent=2) + "\n")
        result = validate_seed_file(seed_json, result_output=validation_json, verify_paths=True)
        self.assertTrue(result["valid"], result["errors"])
        return seed_json, validation_json

    def test_initial_genome_contains_research_backed_axes(self) -> None:
        genome = build_initial_genome(SeedEvidence())
        paths = {gene.path for gene in genome.genes}
        bodies = {gene.body_variant for gene in genome.genes}
        sources = {gene.source for gene in genome.genes}

        self.assertIn("/tools/invoke", paths)
        self.assertIn("/v1/chat/completions", paths)
        self.assertIn("json-path-traversal", bodies)
        self.assertIn("json-command-tokens", bodies)
        self.assertIn("dogpile", sources)
        self.assertIn("runtime_anomaly", sources)
        self.assertTrue(all("Docker-contained" in gene.risk_boundary for gene in genome.genes))

    def test_mutation_is_deterministic_and_preserves_lineage(self) -> None:
        gene = build_initial_genome(SeedEvidence()).genes[0]

        left = mutate_gene(gene, 1234)
        right = mutate_gene(gene, 1234)
        other = mutate_gene(gene, 1235)

        self.assertEqual(left, right)
        self.assertNotEqual(left.gene_id, gene.gene_id)
        self.assertIn(gene.gene_id, left.lineage)
        self.assertNotEqual(left, other)

    def test_scoring_and_promotion_detect_sensitive_success(self) -> None:
        gene = build_initial_genome(SeedEvidence()).genes[2]
        record = AttemptRecord(0, 0, gene, {"status": 200, "elapsed_ms": 12, "body": "metrics token"}, 0.0)
        score = score_attempt(record)
        anomaly = classify_anomaly(AttemptRecord(0, 0, gene, record.result, score))

        self.assertGreaterEqual(score, 12.0)
        self.assertIsNotNone(anomaly)
        self.assertEqual(anomaly.reason, "unexpected-unauthenticated-200")

