    def test_seed_research_validator_rejects_paper_only_native_lane(self) -> None:
        payload = self._valid_seed_payload()
        recommended = payload["recommended_fuzzing_lanes"]
        excluded = payload["excluded_lanes"]
        strategy_set = payload["seedStrategySet"]
        assert isinstance(recommended, list)
        assert isinstance(excluded, list)
        assert isinstance(strategy_set, dict)
        strategies = strategy_set["lane_seed_strategies"]
        assert isinstance(strategies, list)
        native = next(item for item in excluded if item["lane_id"] == "native_binary")
        excluded.remove(native)
        recommended.append(
            {
                "lane_id": "native_binary",
                "supporting_sources": [{"source_type": "paper_url", "source": "https://arxiv.org/abs/2506.23063", "quote_or_fact": "Native fuzzing is useful."}],
                "false_positive_filters": [],
            }
        )
        native_strategy = next(item for item in strategies if item["lane_id"] == "native_binary")
        native_strategy["enabled"] = True
        native_strategy["evidence_gate"] = {"status": "supported", "required_sources": ["paper"], "blocking_unknowns": []}
        native_strategy["starting_genes"] = [{"gene_id": "native-0", "seed_type": "paper_technique", "seed_value": "native fuzzing", "mutation_axes": ["coverage"], "source": "paper"}]
        native_strategy["fitness_signals"] = ["coverage_delta"]

        errors = validate_seed_research_payload(payload)

        self.assertTrue(any("recommended lane native_binary has no target-specific supporting source" in error for error in errors))
        self.assertTrue(any("native_binary must be excluded" in error for error in errors))

